    e = np.array(es)
    return (np.round(e.mean(0), 5), np.round(e.reshape(len(e), -1).mean(1), 5), round(e.max(), 5))

def mat(u, kind, w):
    cols = [np.ones(len(u)), u]
    k = 0
    for t in kind:
        if t == 'q':
            cols.append(u * u)
            continue
        a = w[k:k + 4] * u
        k += 4
        cols.append({'h': np.tanh, 's': np.sin, 'c': np.cos}[t](a))
    return np.column_stack(cols)

def basis(x, terms, w=1.0):
    from itertools import combinations
    b = [np.ones((len(x), 1)), x]
    for t in terms:
        if t == 'q':
            b.append(x * x)
        elif t == 'p':
            b.append(np.column_stack([x[:, i] * x[:, j] for (i, j) in combinations(range(4), 2)]))
        elif t == 's':
            b.append(np.sin(w * x))
        elif t == 'c':
            b.append(np.cos(w * x))
        elif t == 'h':
            b.append(np.tanh(w * x))
        elif t == 'z':
            b.append(x ** 3)
    return np.column_stack(b)

def loo(A, Y):
    (Q, R) = np.linalg.qr(A)
    E = (Y - Q @ (Q.T @ Y)) / np.maximum(1 - (Q * Q).sum(1), 1e-09)[:, None]
    return np.abs(E).mean(0)

def _trajectory(x, target, x_test, t):
    from scipy.optimize import least_squares

